{{pins}}
#include <Servo.h>

Servo lid;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  lid.attach(SERVO_PIN);
  lid.write(90);   // start with the lid closed
}

long measureCm() {
  // Send a 10 microsecond ping...
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  // ...and time how long the echo takes to come back.
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  return duration / 58;  // sound travels 1 cm there and back in about 58 microseconds
}

void loop() {
  long cm = measureCm();
  if (cm > 0 && cm < 30) {   // a hand is close
    digitalWrite(LED_PIN, HIGH);  // light on
    lid.write(0);    // open
    delay(5000);     // stay open for 5 seconds
    lid.write(90);   // close
    digitalWrite(LED_PIN, LOW);   // light off
    delay(1000);
  }
  delay(100);
}
